// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz parameters: from (address) and a single recipient addr and uint v and a length selector to ensure non-empty
    function testFuzz_property(address from, address recipient, uint256 v, uint256 lenNonZero) public {
        // ensure _tos.length > 0 in admissible domain
        uint256 len = (lenNonZero % 3) + 1; // keep small but >=1

        // deploy a recorder that ONLY implements transferFrom(address,address,uint256)
        // and will revert if any other selector is called. This records how many times it was called
        // and the last arguments seen.
        Recorder rec = new Recorder();

        // build tos array with exactly one recipient to keep observation simple
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) tos[i] = recipient;

        // Call c.transfer. The reference implementation will call transferFrom(...) on rec and succeed.
        // The mutant which encodes selector for transfer(...) will not match transferFrom and will therefore
        // invoke fallback on Recorder which reverts. We catch whether c.transfer succeeds.
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: For any inputs, the correct contract C will always succeed (ok == true)
        // because Recorder implements transferFrom and will accept the call. The mutant that uses
        // transfer(...) selector will cause Recorder to revert when fallback is hit, making ok == false
        // for some inputs. We assert the universal property that c.transfer returns (does not revert)
        // for all admissible inputs when interacting with a counterparty that implements transferFrom.
        assertTrue(ok);
    }
}

// Recorder implements exactly the function selector the reference encodes: transferFrom(address,address,uint256)
// It records calls and returns true. If any other selector is invoked (e.g., transfer(...)) the fallback reverts.
contract Recorder {
    uint256 public calls;
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;

    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        return true;
    }

    fallback() external payable {
        // any unexpected selector (like transfer(...)) causes a revert so the mutant will fail
        revert("unexpected selector");
    }

    receive() external payable {
        // not used
    }
}
